import{_ as o,a0 as p,w as n,s as l,ao as u,I as a,x as i,a1 as t,A as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"在 Linux 中運行特定命令而無需 sudo 密碼 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中運行特定命令而無需 sudo 密碼 | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中運行特定命令而無需 sudo 密碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中運行特定命令而無需 sudo 密碼 | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20190214 Run Particular Commands Without Sudo Password In Linux","title":"在 Linux 中運行特定命令而無需 sudo 密碼","tag":"201903","desc":""},"relativePath":"201903/20190214 Run Particular Commands Without Sudo Password In Linux.md","filePath":"[post].md"}'),c={name:"201903/20190214 Run Particular Commands Without Sudo Password In Linux.md"};function r(h,s,k,g,b,m){const e=p("Link");return n(),l("div",null,[s[15]||(s[15]=u(`<h1 id="在-linux-中運行特定命令而無需-sudo-密碼" tabindex="-1">在 Linux 中運行特定命令而無需 sudo 密碼 <a class="header-anchor" href="#在-linux-中運行特定命令而無需-sudo-密碼" aria-label="Permalink to “在 Linux 中運行特定命令而無需 sudo 密碼”">​</a></h1><p>我有一台部署在 AWS 上的 Ubuntu 系統，在它的裏面有一個腳本，這個腳本的原有目的是以一定間隔（準確來説是每隔 1 分鐘）去檢查某個特定服務是否正在運行，如果這個服務因為某些原因停止了，就自動重啓這個服務。但問題是我需要 sudo 權限來開啓這個服務。正如你所知道的那樣，當我們以 sudo 用户運行命令時，我們應該提供密碼，但我並不想這麼做，實際上我想做的是以 sudo 用户的身份運行這個服務但無需提供密碼。假如你曾經經歷過這樣的情形，那麼我知道一個簡單的方法來做到這點。今天，在這個簡短的指南中，我將教你如何在類 Unix 的操作系統中運行特定命令而無需 sudo 密碼。</p><p>就讓我們看看下面的例子吧。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir /ostechnix</span></span>
<span class="line"><span>[sudo] password for sk:</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/05/sudo-password-1.png" alt=""></p><p>正如上面的截圖中看到的那樣，當我在根目錄（<code>/</code>）中創建一個名為 <code>ostechnix</code> 的目錄時，我需要提供 sudo 密碼。每當我們嘗試以 sudo 特權執行一個命令時，我們必須輸入密碼。而在我的預想中，我不想提供 sudo 密碼。下面的內容便是我如何在我的 Linux 機子上運行一個 <code>sudo</code> 命令而無需輸入密碼的過程。</p><h3 id="在-linux-中運行特定命令而無需-sudo-密碼-1" tabindex="-1">在 Linux 中運行特定命令而無需 sudo 密碼 <a class="header-anchor" href="#在-linux-中運行特定命令而無需-sudo-密碼-1" aria-label="Permalink to “在 Linux 中運行特定命令而無需 sudo 密碼”">​</a></h3><p>基於某些原因，假如你想允許一個用户運行特定命令而無需提供 sudo 密碼，則你需要在 <code>sudoers</code> 文件中添加上這個命令。</p><p>假如我想讓名為 <code>sk</code> 的用户去執行 <code>mkdir</code> 而無需提供 sudo 密碼，下面就讓我們看看該如何做到這點。</p><p>使用下面的命令來編輯 <code>sudoers</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo visudo</span></span></code></pre></div><p>將下面的命令添加到這個文件的最後。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sk ALL=NOPASSWD:/bin/mkdir</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/05/sudo-password-7.png" alt=""></p><p>其中 <code>sk</code> 是用户名。根據上面一行的內容，用户 <code>sk</code> 可以從任意終端執行 <code>mkdir</code> 命令而不必輸入 sudo 密碼。</p><p>你可以用逗號分隔的值來添加額外的命令（例如 <code>chmod</code>），正如下面展示的那樣。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sk ALL=NOPASSWD:/bin/mkdir,/bin/chmod</span></span></code></pre></div><p>保存並關閉這個文件，然後註銷（或重啓）你的系統。現在以普通用户 <code>sk</code> 登錄，然後試試使用 <code>sudo</code> 來運行這些命令，看會發生什麼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir /dir1</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/05/sudo-password-6.png" alt=""></p><p>看到了嗎？即便我以 sudo 特權運行 <code>mkdir</code> 命令，也不會彈出提示讓我輸入密碼。從現在開始，當用户 <code>sk</code> 運行 <code>mkdir</code> 時，就不必輸入 sudo 密碼了。</p><p>當運行除了添加到 <code>sudoers</code> 文件之外的命令時，你將被提示輸入 sudo 密碼。</p><p>讓我們用 <code>sudo</code> 來運行另一個命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/05/sudo-password-4.png" alt=""></p><p>看到了嗎？這個命令將提示我輸入 sudo 密碼。</p><p>假如你不想讓這個命令提示你輸入 sudo 密碼，請編輯 <code>sudoers</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo visudo</span></span></code></pre></div><p>像下面這樣將 <code>apt</code> 命令添加到 <code>sudoers</code> 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sk ALL=NOPASSWD:/bin/mkdir,/usr/bin/apt</span></span></code></pre></div><p>你注意到了上面命令中 <code>apt</code> 二進制執行文件的路徑與 <code>mkdir</code> 的有所不同嗎？是的，你必須提供一個正確的可執行文件路徑。要找到任意命令的可執行文件路徑，例如這裏的 <code>apt</code>，可以像下面這樣使用 <code>whichis</code> 命令來查看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ whereis apt</span></span>
<span class="line"><span>apt: /usr/bin/apt /usr/lib/apt /etc/apt /usr/share/man/man8/apt.8.gz</span></span></code></pre></div><p>如你所見，<code>apt</code> 命令的可執行文件路徑為 <code>/usr/bin/apt</code>，所以我將這個路徑添加到了 <code>sudoers</code> 文件中。</p><p>正如我前面提及的那樣，你可以添加任意多個以逗號分隔的命令。一旦你做完添加的動作，保存並關閉你的 <code>sudoers</code> 文件，接着註銷，然後重新登錄進你的系統。</p><p>現在就檢驗你是否可以直接運行以 <code>sudo</code> 開頭的命令而不必使用密碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/05/sudo-password-5.png" alt=""></p><p>看到了嗎？<code>apt</code> 命令沒有讓我輸入 sudo 密碼，即便我用 <code>sudo</code> 來運行它。</p><p>下面展示另一個例子。假如你想運行一個特定服務，例如 <code>apache2</code>，那麼就添加下面這條命令到 <code>sudoers</code> 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sk ALL=NOPASSWD:/bin/mkdir,/usr/bin/apt,/bin/systemctl restart apache2</span></span></code></pre></div><p>現在用户 <code>sk</code> 就可以運行 <code>sudo systemctl restart apache</code> 命令而不必輸入 sudo 密碼了。</p><p>我可以再次讓一個特別的命令提醒輸入 sudo 密碼嗎？當然可以！只需要刪除添加的命令，註銷然後再次登錄即可。</p><p>除了這種方法外，你還可以在命令的前面添加 <code>PASSWD:</code> 指令。讓我們看看下面的例子：</p><p>在 <code>sudoers</code> 文件中添加或者修改下面的一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sk ALL=NOPASSWD:/bin/mkdir,/bin/chmod,PASSWD:/usr/bin/apt</span></span></code></pre></div><p>在這種情況下，用户 <code>sk</code> 可以運行 <code>mkdir</code> 和 <code>chmod</code> 命令而不用輸入 sudo 密碼。然而，當他運行 <code>apt</code> 命令時，就必須提供 sudo 密碼了。</p><p>免責聲明：本篇指南僅具有教育意義。在使用這個方法的時候，你必須非常小心。這個命令既可能富有成效但也可能帶來摧毀性效果。例如，假如你允許用户執行 <code>rm</code> 命令而不輸入 sudo 密碼，那麼他們可能無意或有意地刪除某些重要文件。我警告過你了！</p><p>那麼這就是全部的內容了。希望這個能夠給你帶來幫助。更多精彩內容即將呈現，請保持關注！</p><p>乾杯！</p><hr>`,50)),a("p",null,[s[1]||(s[1]=i("via: ",-1)),t(e,{href:"https://www.ostechnix.com/run-particular-commands-without-sudo-password-linux/"},{default:d(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/run-particular-commands-without-sudo-password-linux/",-1)])]),_:1})]),a("p",null,[s[6]||(s[6]=i("作者：",-1)),t(e,{href:"https://www.ostechnix.com/author/sk/"},{default:d(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[7]||(s[7]=i(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:d(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 譯者：",-1)),t(e,{href:"https://github.com/FSSlc"},{default:d(()=>[...s[4]||(s[4]=[i("FSSlc",-1)])]),_:1}),s[9]||(s[9]=i(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:d(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[12]||(s[12]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:d(()=>[...s[11]||(s[11]=[i("Linux中國",-1)])]),_:1}),s[14]||(s[14]=i(" 榮譽推出",-1))])])}const C=o(c,[["render",r]]);export{w as __pageData,C as default};
